def lower_bound(nums, target):
    low = 0
    high = len(nums)
    while low < high:
        mid = (low + high) // 2
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

print(lower_bound([1, 2, 2, 2, 3], 2))
print(lower_bound([1, 2, 2, 2, 3], 4))
print(lower_bound([], 5))
